export type AsciiHoverColor =
  | "default"
  | "emerald"
  | "blue"
  | "violet"
  | "amber"
  | "rose"
  | "cyan";

export interface AsciiColorPalette {
  dark: {
    text: string;
    glow: string;
  };
  light: {
    text: string;
    glow: string;
  };
}

const COLOR_PALETTES: Record<AsciiHoverColor, AsciiColorPalette> = {
  default: {
    dark: {
      text: "#ffffff",
      glow: "rgba(255, 255, 255, 0.4)",
    },
